/**
 * FILE: concept_8_venture_capital_lightbulb.js
 * THEME: Finance & Investment — Bright Financial Idea & Startup Capital Lightbulb
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Fundamental harmonic phases for 100% seamless 20-second loop
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau + currentScene * 0;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;

  // Color Palette (Crisp Commercial Flat Vector, Zero Glow/Bloom)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#162035',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    slateDark: '#334155',
    slateMid: '#64748B',
    bulbCyanLight: '#E0F2FE',
    bulbCyanMid: '#7DD3FC',
    bulbCyanDark: '#38BDF8',
    goldLight: '#FEF08A',
    goldMid: '#FACC15',
    goldDark: '#EAB308',
    goldDeep: '#CA8A04',
    orangeLight: '#FED7AA',
    orangeMid: '#FB923C',
    orangeDark: '#EA580C',
    emeraldLight: '#A7F3D0',
    emeraldMid: '#22C55E',
    emeraldDark: '#15803D',
    rocketRed: '#F43F5E',
    purpleMid: '#A855F7'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Emblem
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 13 * scaleSize;
    const h = 20 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Gold Coin Medallion
  function drawGoldMedallion(centerX, centerY, radius, dollarScale) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, tau);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.arc(centerX, centerY, radius * 0.74, 0, tau);
    fillAndStroke(COL.goldLight, COL.outline, 2.5 * s);

    drawVectorDollar(centerX, centerY, dollarScale, COL.outline, 3.2 * s);
  }

  // Helper: Side-View Stacked Coin Cylinder
  function drawCoinCylinder(centerX, topY, coinW, coinH) {
    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    roundedRectPath(centerX - coinW * 0.40, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldLight, null, 0);

    roundedRectPath(centerX + coinW * 0.20, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldDeep, null, 0);

    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(null, COL.outline, thinStrokeW);
  }

  // Helper: Systematic involute-style mechanical gear with symmetric tooth centered at local angle 0
  // Tooth centered at 0, valley centered at step/2 -> guarantees exact mathematical meshing without collision
  function drawSystematicGear(centerX, centerY, pitchR, teethCount, rotationAngle, bodyColor, ringR, holeR) {
    const addendum = 6.2 * s;
    const dedendum = 7.8 * s;
    const outerR = pitchR + addendum;
    const rootR = pitchR - dedendum;
    const step = tau / teethCount;

    ctx.save();
    ctx.translate(centerX, centerY);
    ctx.rotate(rotationAngle);

    ctx.beginPath();
    for (let i = 0; i < teethCount; i++) {
      const aCenter = i * step;
      // Tooth top land spans [-0.13*step, +0.13*step]
      // Flanks slope down to root at [-0.26*step, +0.26*step]
      // Valley bottom land spans [+0.26*step, +0.74*step]
      const aRootLeft = aCenter - step * 0.26;
      const aTipLeft = aCenter - step * 0.13;
      const aTipRight = aCenter + step * 0.13;
      const aRootRight = aCenter + step * 0.26;
      const aNextRootLeft = aCenter + step * 0.74;

      if (i === 0) {
        ctx.moveTo(Math.cos(aRootLeft) * rootR, Math.sin(aRootLeft) * rootR);
      } else {
        ctx.lineTo(Math.cos(aRootLeft) * rootR, Math.sin(aRootLeft) * rootR);
      }
      ctx.lineTo(Math.cos(aTipLeft) * outerR, Math.sin(aTipLeft) * outerR);
      ctx.arc(0, 0, outerR, aTipLeft, aTipRight, false);
      ctx.lineTo(Math.cos(aRootRight) * rootR, Math.sin(aRootRight) * rootR);
      ctx.arc(0, 0, rootR, aRootRight, aNextRootLeft, false);
    }
    ctx.closePath();
    fillAndStroke(bodyColor, COL.outline, thinStrokeW);

    // Inner structural hub ring
    ctx.beginPath();
    ctx.arc(0, 0, ringR, 0, tau);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.8 * s);

    // 4 Rotating Hub Alignment Markers (Visualizes proportional angular velocity clearly)
    for (let k = 0; k < 4; k++) {
      const ka = (k * Math.PI) * 0.5;
      const dotDist = (ringR + holeR) * 0.5;
      ctx.beginPath();
      ctx.arc(Math.cos(ka) * dotDist, Math.sin(ka) * dotDist, 2.2 * s, 0, tau);
      ctx.fillStyle = COL.outline;
      ctx.fill();
    }

    // Center axle bore
    ctx.beginPath();
    ctx.arc(0, 0, holeR, 0, tau);
    fillAndStroke(COL.slateDark, COL.outline, 2.5 * s);

    ctx.restore();
  }

  // Helper: Continuous Seamless Lightbulb Envelope Path
  function traceLightbulbGlassPath(centerX, sphereCY, sphereR, neckHalfW, neckBotY) {
    const joinAngle = Math.acos(neckHalfW / sphereR);
    const cornerR = 14 * s;
    ctx.beginPath();
    ctx.moveTo(centerX - neckHalfW + cornerR, neckBotY);
    ctx.arcTo(centerX - neckHalfW, neckBotY, centerX - neckHalfW, neckBotY - cornerR, cornerR);
    ctx.arc(centerX, sphereCY, sphereR, Math.PI - joinAngle, joinAngle, false);
    ctx.lineTo(centerX + neckHalfW, neckBotY - cornerR);
    ctx.arcTo(centerX + neckHalfW, neckBotY, centerX + neckHalfW - cornerR, neckBotY, cornerR);
    ctx.closePath();
  }

  // =========================================================================
  // 2. STRUCTURAL BASELINE PLATFORM & NON-INTERSECTING CIRCUIT BRIDGES
  // =========================================================================
  const baseLineY = cy + 395 * s;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 735 * s, baseLineY);
  ctx.lineTo(cx + 735 * s, baseLineY);
  ctx.stroke();

  // Outer baseline accent ticks
  const tickShift = Math.sin(p2) * 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 810 * s - tickShift, baseLineY);
  ctx.lineTo(cx - 760 * s - tickShift, baseLineY);
  ctx.moveTo(cx + 760 * s + tickShift, baseLineY);
  ctx.lineTo(cx + 810 * s + tickShift, baseLineY);
  ctx.stroke();

  // Sub-platform line
  ctx.beginPath();
  ctx.moveTo(cx - 360 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 360 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Dedicated Horizontal Circuit Bridges in Lower Corridor (y = cy + 205*s)
  const bridgeY = cy + 205 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 282 * s, bridgeY);
  ctx.lineTo(cx - 224 * s, bridgeY);
  ctx.moveTo(cx + 224 * s, bridgeY);
  ctx.lineTo(cx + 282 * s, bridgeY);
  ctx.stroke();

  const bProgL = (sceneProgress * 4) % 1;
  ctx.beginPath();
  ctx.arc(cx - 276 * s + bProgL * 46 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.bulbCyanDark, COL.outline, 2.5 * s);

  const bProgR = (sceneProgress * 4 + 0.5) % 1;
  ctx.beginPath();
  ctx.arc(cx + 230 * s + bProgR * 46 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // =========================================================================
  // 3. LEFT-TOP ZONE: VENTURE CAPITAL CONTRACT & SEED FUNDING CARD
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy - 360*s, cy - 35*s]
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 4.5 * s;
  const ltX = cx - 685 * s;
  const ltY = cy - 360 * s + ltFloatY;
  const ltW = 390 * s;
  const ltH = 315 * s;

  roundedRectPath(ltX, ltY, ltW, ltH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Top Header Strip inside Left-Top Card
  roundedRectPath(ltX + 18 * s, ltY + 18 * s, ltW - 36 * s, 46 * s, 12 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  const headerDots = [COL.bulbCyanDark, COL.goldMid, COL.emeraldMid];
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(ltX + 40 * s + d * 24 * s, ltY + 41 * s, 7 * s, 0, tau);
    fillAndStroke(headerDots[d], COL.outline, 2.5 * s);
  }

  roundedRectPath(ltX + 118 * s, ltY + 35 * s, 150 * s, 12 * s, 6 * s);
  fillAndStroke(COL.slateDark, null, 0);

  roundedRectPath(ltX + ltW - 102 * s, ltY + 27 * s, 68 * s, 28 * s, 8 * s);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // Left Sub-Box inside Card: Investment Contract Document Sheet
  const docX = ltX + 20 * s;
  const docY = ltY + 82 * s;
  const docW = 148 * s;
  const docH = 212 * s;

  roundedRectPath(docX, docY, docW, docH, 14 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  drawGoldMedallion(docX + 44 * s, docY + 42 * s, 22 * s, 0.65 * s);

  roundedRectPath(docX + 76 * s, docY + 30 * s, 54 * s, 10 * s, 5 * s);
  fillAndStroke(COL.slateDark, null, 0);
  roundedRectPath(docX + 76 * s, docY + 46 * s, 40 * s, 8 * s, 4 * s);
  fillAndStroke(COL.slateMid, null, 0);

  for (let cl = 0; cl < 4; cl++) {
    const cly = docY + 84 * s + cl * 22 * s;
    const clw = (cl === 3 ? 76 : 112) * s;
    roundedRectPath(docX + 18 * s, cly, clw, 8 * s, 4 * s);
    fillAndStroke(COL.slateMid, null, 0);
  }

  roundedRectPath(docX + 18 * s, docY + docH - 38 * s, docW - 36 * s, 24 * s, 8 * s);
  fillAndStroke(COL.emeraldMid, COL.outline, 2.5 * s);

  // Right Sub-Box inside Card: 3 Funding Round Progress Bars
  const roundX = ltX + 186 * s;
  const roundW = 184 * s;
  const roundColors = [COL.bulbCyanDark, COL.goldMid, COL.emeraldMid];

  for (let r = 0; r < 3; r++) {
    const ry = ltY + 86 * s + r * 70 * s;
    roundedRectPath(roundX, ry, roundW, 56 * s, 12 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.8 * s);

    roundedRectPath(roundX + 14 * s, ry + 12 * s, 72 * s, 9 * s, 4.5 * s);
    fillAndStroke(COL.slateDark, null, 0);

    ctx.beginPath();
    ctx.arc(roundX + roundW - 22 * s, ry + 16 * s, 6 * s, 0, tau);
    fillAndStroke(roundColors[r], COL.outline, 2 * s);

    roundedRectPath(roundX + 14 * s, ry + 30 * s, roundW - 28 * s, 14 * s, 7 * s);
    fillAndStroke(COL.surfaceWhite, COL.outline, 2.2 * s);

    const fillW = (0.58 + 0.30 * Math.sin(p2 - r * 1.05)) * (roundW - 34 * s);
    roundedRectPath(roundX + 17 * s, ry + 33 * s, fillW, 8 * s, 4 * s);
    fillAndStroke(roundColors[r], null, 0);
  }

  // =========================================================================
  // 4. LEFT-BOTTOM ZONE: SYSTEMATIC GEARS CARD & GOLD RESERVES PEDESTAL
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy + 25*s, cy + 395*s]
  // =========================================================================
  const lbFloatY = Math.cos(p2) * 4 * s;
  const lbX = cx - 685 * s;
  const lbY = cy + 25 * s + lbFloatY;
  const lbW = 390 * s;
  const lbCardH = 190 * s;

  // 4A. Upper Business Mechanism Gears Card
  roundedRectPath(lbX, lbY, lbW, lbCardH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Dedicated Gear Housing Frame on Left of Card
  roundedRectPath(lbX + 16 * s, lbY + 18 * s, 172 * s, lbCardH - 36 * s, 14 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, 2.5 * s);

  // Two Proportionally & Mathematically Meshed Gears:
  // Gear 1 (Gold Driver): N1 = 8 teeth, module m = 5.0*s -> Pitch Radius R1 = 40*s
  // Gear 2 (Cyan Driven): N2 = 6 teeth, module m = 5.0*s -> Pitch Radius R2 = 30*s
  // Exact Center Distance = R1 + R2 + strokeClearance = 40*s + 30*s + 3.5*s = 73.5*s
  // Line of Centers Angle phi = 28 degrees (0.48869 rad)
  // For integer 20-second loop:
  //   Gear 1 completes 3 full clockwise turns -> omega1 = 3 * p1
  //   Gear 2 completes 3 * (8/6) = 4 full counter-clockwise turns -> omega2 = -4 * p1
  // Exact Meshing Phase Alignment along line of centers phi:
  //   theta1_0 = phi
  //   theta2_0 = phi + Math.PI + (Math.PI / N2)
  const N1 = 8;
  const N2 = 6;
  const pitchR1 = 40 * s;
  const pitchR2 = 30 * s;
  const centerDist = 73.5 * s;
  const meshPhi = 0.488692; // 28 degrees

  const gear1CX = lbX + 74 * s;
  const gear1CY = lbY + 78 * s;
  const gear2CX = gear1CX + Math.cos(meshPhi) * centerDist;
  const gear2CY = gear1CY + Math.sin(meshPhi) * centerDist;

  const theta1 = meshPhi + p3;
  const theta2 = meshPhi + Math.PI + (Math.PI / N2) - p4;

  // Draw subtle transmission link bar behind gears connecting axles
  ctx.strokeStyle = COL.surfaceMuted;
  ctx.lineWidth = 6 * s;
  ctx.beginPath();
  ctx.moveTo(gear1CX, gear1CY);
  ctx.lineTo(gear2CX, gear2CY);
  ctx.stroke();

  drawSystematicGear(gear1CX, gear1CY, pitchR1, N1, theta1, COL.goldMid, 21 * s, 11 * s);
  drawSystematicGear(gear2CX, gear2CY, pitchR2, N2, theta2, COL.bulbCyanDark, 15.5 * s, 8 * s);

  // Right 3 Operational Efficiency Meters inside Card
  const effStartX = lbX + 204 * s;
  const effWidth = 166 * s;
  for (let m = 0; m < 3; m++) {
    const my = lbY + 34 * s + m * 48 * s;
    roundedRectPath(effStartX, my, 76 * s, 9 * s, 4.5 * s);
    fillAndStroke(COL.slateMid, null, 0);

    roundedRectPath(effStartX, my + 15 * s, effWidth, 18 * s, 9 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.5 * s);

    const mFill = (0.55 + 0.28 * Math.sin(p2 + m * 1.2)) * (effWidth - 6 * s);
    roundedRectPath(effStartX + 3 * s, my + 18 * s, mFill, 12 * s, 6 * s);
    fillAndStroke(headerDots[m], null, 0);
  }

  // 4B. Lower Gold Bullion & Coin Pedestal on baseLineY
  const pedLX = lbX;
  const pedLW = lbW;
  const pedLH = 24 * s;
  const pedLY = baseLineY - pedLH;

  roundedRectPath(pedLX, pedLY, pedLW, pedLH, 8 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  function drawBullionBar(centerX, bottomY, barW, barH) {
    const topW = barW * 0.78;
    ctx.beginPath();
    ctx.moveTo(centerX - barW * 0.5, bottomY);
    ctx.lineTo(centerX - topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + barW * 0.5, bottomY);
    ctx.closePath();
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.moveTo(centerX - topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.42, bottomY - 7 * s);
    ctx.lineTo(centerX - topW * 0.42, bottomY - 7 * s);
    ctx.closePath();
    fillAndStroke(COL.goldLight, null, 0);
  }

  // Column 1 (Left): 2 Stacked Gold Bullion Bars (x center = lbX + 84*s, spans [22, 146])
  const bulCX = lbX + 84 * s;
  drawBullionBar(bulCX, pedLY, 124 * s, 38 * s);
  drawBullionBar(bulCX, pedLY - 38 * s, 108 * s, 36 * s);

  // Column 2 (Middle): 4 Stacked Gold Coins (x center = lbX + 216*s, spans [174, 258], 28*s clear gap!)
  const stackLCX = lbX + 216 * s;
  const cH = 24 * s;
  for (let c = 0; c < 4; c++) {
    drawCoinCylinder(stackLCX, pedLY - (c + 1) * cH, 84 * s, cH);
  }

  // Column 3 (Right): Front Gold Dollar Medallion on Stand (x center = lbX + 330*s, spans [286, 374], 28*s clear gap!)
  const medLCX = lbX + 330 * s;
  const medLCY = pedLY - 64 * s + Math.sin(p2) * 4 * s;
  roundedRectPath(medLCX - 22 * s, pedLY - 16 * s, 44 * s, 16 * s, 5 * s);
  fillAndStroke(COL.goldDeep, COL.outline, thinStrokeW);
  drawGoldMedallion(medLCX, medLCY, 44 * s, 1.25 * s);

  // =========================================================================
  // 5. CENTER ZONE: VENTURE CAPITAL LIGHTBULB HUB & SOLID RAYS
  // Bulb Sphere Center: (cx, cy - 68*s), Radius: 156*s
  // =========================================================================
  const bulbFloatY = Math.sin(p2) * 4.5 * s;
  const bulbCX = cx;
  const sphereCY = cy - 68 * s + bulbFloatY;
  const sphereR = 156 * s;
  const neckHalfW = 85 * s;
  const neckBotY = sphereCY + 206 * s;

  // 5A. Central Pedestal Dock on baseLineY
  roundedRectPath(cx - 86 * s, cy + 322 * s, 172 * s, 40 * s, 10 * s);
  fillAndStroke(COL.slateMid, COL.outline, strokeW);

  roundedRectPath(cx - 142 * s, baseLineY - 38 * s, 284 * s, 38 * s, 12 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  roundedRectPath(cx - 96 * s, baseLineY - 22 * s, 192 * s, 10 * s, 5 * s);
  fillAndStroke(COL.goldMid, null, 0);

  // 5B. 9 Solid Flat Vector Ray Pills Around Bulb Upper Dome
  const rayCount = 9;
  for (let r = 0; r < rayCount; r++) {
    const deg = -168 + r * (156 / (rayCount - 1));
    const rad = (deg * Math.PI) / 180;
    const rayWave = 0.5 + 0.5 * Math.sin(p4 - r * 0.55);
    const rStart = sphereR + 20 * s;
    const rLen = (28 + rayWave * 14) * s;

    ctx.save();
    ctx.translate(bulbCX, sphereCY);
    ctx.rotate(rad);
    roundedRectPath(rStart, -7 * s, rLen, 14 * s, 7 * s);
    fillAndStroke(r % 2 === 0 ? COL.goldMid : COL.orangeMid, COL.outline, thinStrokeW);
    ctx.restore();
  }

  // 5C. Threaded Gold Screw Base & Bottom Contact Point
  const ribWidths = [154 * s, 138 * s, 118 * s];
  const ribH = 24 * s;
  for (let rb = 0; rb < 3; rb++) {
    const rw = ribWidths[rb];
    const ry = neckBotY + rb * (ribH - 2 * s);
    roundedRectPath(bulbCX - rw * 0.5, ry, rw, ribH, 11 * s);
    fillAndStroke(rb % 2 === 0 ? COL.goldMid : COL.goldDark, COL.outline, strokeW);
  }

  const contactTopY = neckBotY + 3 * (ribH - 2 * s) - 2 * s;
  ctx.beginPath();
  ctx.moveTo(bulbCX - 44 * s, contactTopY);
